CREATE OR REPLACE FUNCTION public.delete_message(p_message_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_sender_id UUID;
  v_caller_id UUID;
BEGIN
  v_caller_id := auth.uid();
  IF v_caller_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  SELECT sender_id INTO v_sender_id
  FROM public.messages
  WHERE id = p_message_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Message not found';
  END IF;

  IF v_sender_id != v_caller_id THEN
    RAISE EXCEPTION 'You can only delete your own messages';
  END IF;

  DELETE FROM public.messages
  WHERE id = p_message_id;

  RETURN TRUE;
END;
$function$

CREATE OR REPLACE FUNCTION public.get_or_create_dm(other_user_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_conversation_id uuid;
begin
  if v_user_id is null or other_user_id = v_user_id then
    raise exception 'Invalid direct-message recipient';
  end if;
  if not exists (
    select 1 from public.friend_requests
    where status = 'accepted'
      and (
        (sender_id = v_user_id and receiver_id = other_user_id)
        or (sender_id = other_user_id and receiver_id = v_user_id)
      )
  ) then
    raise exception 'You can only message connected builders';
  end if;

  perform pg_advisory_xact_lock(
    hashtextextended(least(v_user_id::text, other_user_id::text) || ':' ||
      greatest(v_user_id::text, other_user_id::text), 1)
  );

  select c.id into v_conversation_id
  from public.conversations c
  where c.type = 'dm'
    and exists (
      select 1 from public.conversation_participants p
      where p.conversation_id = c.id and p.user_id = v_user_id
    )
    and exists (
      select 1 from public.conversation_participants p
      where p.conversation_id = c.id and p.user_id = other_user_id
    )
  limit 1;

  if v_conversation_id is null then
    insert into public.conversations (type)
    values ('dm')
    returning id into v_conversation_id;
    insert into public.conversation_participants (conversation_id, user_id)
    values
      (v_conversation_id, v_user_id),
      (v_conversation_id, other_user_id);
  end if;

  return v_conversation_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.pin_message(p_message_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_conversation_id uuid;
BEGIN
  SELECT conversation_id
  INTO v_conversation_id
  FROM messages
  WHERE id = p_message_id;

  IF v_conversation_id IS NULL THEN
    RAISE EXCEPTION 'Message not found';
  END IF;

  IF NOT can_access_conversation(v_conversation_id) THEN
    RAISE EXCEPTION 'Conversation access denied';
  END IF;

  UPDATE messages
  SET is_pinned = false
  WHERE conversation_id = v_conversation_id;

  UPDATE messages
  SET is_pinned = true
  WHERE id = p_message_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.send_message_with_mentions(p_conversation_id uuid, p_content text, p_mentions uuid[] DEFAULT ARRAY[]::uuid[], p_reply_to_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_content text := btrim(p_content);
  v_message_id uuid;
  v_match text[];
  v_url text;
  v_domain text;
  v_allowed text[] := array[
    'github.com', 'gitlab.com', 'bitbucket.org', 'vercel.app', 'netlify.app',
    'figma.com', 'miro.com', 'notion.so', 'notion.site', 'discord.gg',
    'discord.com', 'whatsapp.com', 'slack.com', 'zoom.us', 'meet.google.com',
    'google.com', 'linkedin.com', 'x.com', 'twitter.com', 'unstop.com',
    'devpost.com', 'r2.dev', 'cloudflare.com', 'cloudflarestorage.com',
    'supabase.co', 'hackermate.in'
  ];
BEGIN
  IF (
    SELECT count(*)
    FROM public.messages
    WHERE sender_id = auth.uid()
      AND created_at > now() - interval '10 seconds'
  ) >= 5 THEN
    RAISE EXCEPTION 'You are sending messages too fast. Please wait a moment.';
  END IF;

  IF NOT public.can_access_conversation(p_conversation_id) THEN
    RAISE EXCEPTION 'Conversation access denied';
  END IF;
  IF v_content IS NULL OR char_length(v_content) = 0 OR char_length(v_content) > 5000 THEN
    RAISE EXCEPTION 'Messages must contain between 1 and 5000 characters';
  END IF;
  IF v_content ~* '\m(fuck|shit|bitch|asshole|bastard|cunt|dick|pussy|motherfuck|whore|slut|faggot|nigger|chutiya|bhenchod|madarchod|gandu|bsdk)\M' THEN
    RAISE EXCEPTION 'Message blocked by the community safety filter';
  END IF;

  -- Exempt structured system attachments or validate link domains
  IF NOT (v_content LIKE '__IMAGE__::%' OR v_content LIKE '__VOICE__::%' OR v_content LIKE '__TEAM_INVITE__::%') THEN
    FOR v_match IN
      SELECT regexp_matches(
        v_content,
        '(https?://[^[:space:]]+|www\.[^[:space:]]+|[a-zA-Z0-9.-]+\.(com|org|net|in|co|io|edu|gov|us|xyz|info|biz|me|cc|tv|dev)(/[^[:space:]]*)?)',
        'gi'
      )
    LOOP
      v_url := lower(v_match[1]);
      v_domain := regexp_replace(v_url, '^(https?://)?(www\.)?([^/:?#]+).*$', '\3');
      IF NOT EXISTS (
        SELECT 1 FROM unnest(v_allowed) allowed
        WHERE v_domain = allowed OR right(v_domain, char_length(allowed) + 1) = '.' || allowed
      ) THEN
        RAISE EXCEPTION 'This link domain is not allowed in HackerMate messages';
      END IF;
    END LOOP;
  END IF;

  INSERT INTO public.messages (conversation_id, sender_id, content, reply_to_id, mentions)
  VALUES (p_conversation_id, auth.uid(), v_content, p_reply_to_id, p_mentions)
  RETURNING id INTO v_message_id;

  RETURN v_message_id;
END;
$function$

